B.aNn=new A.a("\u062a\u0648\u062c\u0647\u062a \u0633\u0631\u064a\u0629 \u0642\u0648\u062a\u0647\u0627 \u062b\u0644\u0627\u062b\u064a\u0646 \u0641\u0627\u0631\u0633\u0627\u064b \u0628\u0642\u064a\u0627\u062f\u0629 \u062e\u0627\u0644\u062f \u0628\u0646 \u0627\u0644\u0648\u0644\u064a\u062f \u0627\u0644\u0649 \u0627\u0644\u0637\u0627\u063a\u0648\u062a \u0627\u0644\u0623\u0639\u0638\u0645 \u0645\u0646\u0632\u0644\u0629 \u0648\u0645\u0643\u0627\u0646\u0629 \u0639\u0646\u062f \u0642\u0631\u064a\u0634 \u0648\u0633\u0627\u0626\u0631 \u0627\u0644\u0639\u0631\u0628 \u0627\u0644\u0639\u0632\u0649 \u0644\u0625\u0632\u0627\u0644\u062a\u0647 \u0645\u0646 \u0627\u0644\u0648\u062c\u0648\u062f \u0646\u0647\u0627\u0626\u064a\u0627\u064b \u0648\u0639\u0646\u062f\u0645\u0627 \u0648\u0635\u0644\u062a \u0627\u0644\u0633\u0631\u064a\u0629 \u0627\u0644\u0649 \u0627\u0644\u0639\u0632\u0649 \u0628\u0645\u0646\u0637\u0642\u0629 \u0646\u062e\u0644\u0629 \u0642\u0627\u0645 \u0625\u0644\u064a\u0647\u0627 \u062e\u0627\u0644\u062f \u0641\u0642\u0637\u0639 \u0627\u0644\u0633\u0645\u0631\u0627\u062a \u0648\u0647\u062f\u0645 \u0627\u0644\u0628\u064a\u062a \u0627\u0644\u0630\u064a \u0643\u0627\u0646 \u0639\u0644\u064a\u0647\u060c \u0648\u0647\u0648 \u064a\u0631\u062f\u062f \u0643\u0641\u0631\u0627\u0646\u0643 \u0644\u0627 \u0633\u0628\u062d\u0627\u0646\u0643 \u0625\u0646\u064a \u0631\u0627\u064a\u062a \u0627\u0644\u0644\u0647 \u0642\u062f \u0623\u0647\u0627\u0646\u0643\u060c \u062b\u0645 \u0631\u062c\u0639 \u062e\u0627\u0644\u062f \u0648\u0623\u0635\u062d\u0627\u0628\u0647 \u0627\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0642\u062f\u0645 \u062a\u0642\u0631\u064a\u0631\u0647 \u0628\u0625\u0646\u062c\u0627\u0632 \u0627\u0644\u0645\u0647\u0645\u0629\u060c \u0648\u0644\u0643\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0627\u0633\u062a\u062f\u0631\u0643 \u0639\u0644\u0649 \u0642\u0627\u0626\u062f \u0627\u0644\u0633\u0631\u064a\u0629 \u0648\u0642\u0627\u0644 \u0644\u0647 \u0647\u0644 \u0631\u0623\u064a\u062a \u0634\u064a\u0626\u0627\u064b\u061f \u0642\u0627\u0644: \u0644\u0627 \u0641\u0642\u0627\u0644: \u0627\u0631\u062c\u0639 \u0641\u0625\u0646\u0643 \u0644\u0645 \u062a\u0635\u0646\u0639 \u0634\u064a\u0626\u0627\u064b\u060c \u0641\u0631\u062c\u0639 \u062e\u0627\u0644\u062f \u0648\u0647\u0648 \u0645\u063a\u062a\u0628\u0637 \u062d\u0646\u0642 \u0639\u0644\u0649 \u0639\u062f\u0645 \u0625\u0646\u0647\u0627\u0621 \u0645\u0647\u0645\u062a\u0647 \u0639\u0644\u0649 \u0627\u0644\u0648\u062c\u0647 \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u060c \u0641\u0644\u0645\u0627 \u0648\u0635\u0644 \u0625\u0644\u064a\u0647\u0627 \u0648\u0646\u0638\u0631\u062a \u0627\u0644\u0633\u062f\u0646\u0629 \u0625\u0644\u064a\u0647 \u0639\u0631\u0641\u0648\u0627 \u0623\u0646\u0647 \u062c\u0627\u0621 \u0647\u0630\u0647 \u0627\u0644\u0645\u0631\u0629 \u0644\u064a\u0643\u0645\u0644 \u0645\u0627\u0641\u0627\u062a\u0647 \u0641\u064a \u0627\u0644\u0645\u0631\u0629 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0641\u0647\u0631\u0628\u0648\u0627 \u0627\u0644\u0649 \u0627\u0644\u062c\u0628\u0644 \u0648\u0647\u0648 \u064a\u0635\u064a\u062d\u0648\u0646: \u064a\u0627\u0639\u0632\u0649 \u062e\u0628\u0644\u064a\u0647\u060c \u064a\u0627\u0639\u0632\u0649 \u0639\u0648\u0631\u064a\u0647 \u0641\u0623\u062a\u0627\u0647 \u062e\u0627\u0644\u062f \u0641\u0625\u0630\u0627 \u0627\u0645\u0631\u0623\u0629 \u0639\u0631\u064a\u0627\u0646\u0629 \u0646\u0627\u0634\u0631\u0629 \u0634\u0639\u0631\u0647\u0627 \u062a\u062d\u062b\u0648 \u0627\u0644\u062a\u0631\u0627\u0628 \u0639\u0644\u0649 \u0631\u0623\u0633\u0647\u0627\u060c \u0641\u062a\u0642\u062f\u0645 \u0625\u0644\u064a\u0647\u0627 \u062e\u0627\u0644\u062f \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0628\u0634\u062c\u0627\u0639\u062a\u0647 \u0627\u0644\u0645\u0639\u0631\u0648\u0641\u0629 \u0648\u0636\u0631\u0628\u0647\u0627 \u0628\u0627\u0644\u0633\u064a\u0641 \u062d\u062a\u0649 \u0642\u062a\u0644\u0647\u0627 \u062b\u0645 \u0631\u062c\u0639 \u0627\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0623\u062e\u0628\u0631\u0647 \u0628\u0630\u0644\u0643 \u0641\u0642\u0627\u0644: \u062a\u0644\u0643 \u0647\u064a \u0627\u0644\u0639\u0632\u0649.",null)
