B.aCQ=new A.a("\u0643\u0627\u0646\u062a \u0627\u0644\u0625\u0633\u0631\u0627\u0621 \u0648\u0627\u0644\u0645\u0639\u0631\u0627\u062c \u0642\u0628\u0644 \u0647\u062c\u0631\u062a\u0647 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0628\u0633\u0646\u0629\u060c \u0648\u0644\u0645\u0627 \u0631\u062c\u0639 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0645\u0646 \u0631\u062d\u0644\u062a\u0647 \u0627\u0644\u0645\u064a\u0645\u0648\u0646\u0629 \u0623\u062e\u0628\u0631 \u0642\u0648\u0645\u0647 \u0628\u0630\u0644\u0643 \u0641\u0642\u0627\u0644 \u0644\u0647\u0645 \u0641\u064a \u0645\u062c\u0644\u0633 \u062d\u0636\u0631\u0647 \u0627\u0644\u0645\u0637\u0639\u0645 \u0628\u0646 \u0639\u062f\u064a\u060c \u0648\u0639\u0645\u0631\u0648 \u0628\u0646 \u0647\u0634\u0627\u0645 \u0648\u0627\u0644\u0648\u0644\u064a\u062f \u0628\u0646 \u0627\u0644\u0645\u063a\u064a\u0631\u0629\u060c \u0641\u0642\u0627\u0644: \u0625\u0646\u064a \u0635\u0644\u064a\u062a \u0627\u0644\u0644\u064a\u0644\u0629 \u0627\u0644\u0639\u0634\u0627\u0621 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0645\u0633\u062c\u062f\u060c \u0648\u0635\u0644\u064a\u062a \u0628\u0647 \u0627\u0644\u063a\u062f\u0627\u0629\u060c \u0648\u0623\u062a\u064a\u062a \u0641\u064a\u0645\u0627 \u062f\u0648\u0646 \u0630\u0644\u0643 \u0628\u064a\u062a \u0627\u0644\u0645\u0642\u062f\u0633\u060c \u0641\u0646\u0634\u0631 \u0644\u064a \u0631\u0647\u0637 \u0645\u0646 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0645\u0646\u0647\u0645 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0648\u0645\u0648\u0633\u0649 \u0648\u0639\u064a\u0633\u0649 \u0648\u0635\u0644\u064a\u062a \u0628\u0647\u0645 \u0648\u0643\u0644\u0645\u062a\u0647\u0645 \u0641\u0642\u0627\u0644 \u0639\u0645\u0631\u0648 \u0628\u0646 \u0647\u0634\u0627\u0645 \u0643\u0627\u0644\u0645\u0633\u062a\u0647\u0632\u0626 \u0628\u0647: \u0635\u0641\u0647\u0645 \u0644\u064a\u060c \u0641\u0642\u0627\u0644: \u0623\u0645\u0627 \u0639\u064a\u0633\u0649\u060c \u0641\u0641\u0648\u0642 \u0627\u0644\u0631\u0628\u0639\u0629\u060c \u0648\u062f\u0648\u0646 \u0627\u0644\u0637\u0648\u0644\u060c \u0639\u0631\u064a\u0636 \u0627\u0644\u0635\u062f\u0631\u060c \u0638\u0627\u0647\u0631 \u0627\u0644\u062f\u0645\u060c \u062c\u0639\u062f\u060c \u0623\u0634\u0639\u0631 \u062a\u0639\u0644\u0648\u0647 \u0635\u0647\u0628\u0629 -\u0628\u064a\u0627\u0636 \u0628\u062d\u0645\u0631\u0629 -\u060c\u0643\u0623\u0646\u0647 \u0639\u0631\u0648\u0629 \u0628\u0646 \u0645\u0633\u0639\u0648\u062f \u0627\u0644\u062b\u0642\u0641\u064a\u060c \u0648\u0623\u0645\u0627 \u0645\u0648\u0633\u0649 \u0641\u0636\u062e\u0645 \u0622\u062f\u0645 \u0637\u0648\u0627\u0644\u060c \u0643\u0623\u0646\u0647 \u0645\u0646 \u0631\u062c\u0627\u0644 \u0634\u0646\u0648\u0621\u0629\u060c \u0645\u062a\u0631\u0627\u0643\u0628 \u0627\u0644\u0623\u0633\u0646\u0627\u0646\u060c \u0645\u0642\u0644\u0635 \u0627\u0644\u0634\u0641\u0629\u060c \u062e\u0627\u0631\u062c \u0627\u0644\u0644\u062b\u0629\u060c \u0639\u0627\u0628\u0633\u060c \u0648\u0623\u0645\u0627 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0641\u0648\u0627\u0644\u0644\u0647 \u0625\u0646\u0647 \u0644\u0623\u0634\u0628\u0647 \u0627\u0644\u0646\u0627\u0633 \u0628\u064a \u062e\u064e\u0644\u0642\u0627 \u0648\u062e\u064f\u0644\u0642\u0627.",null)
B.ayd=new A.a("\u0641\u0642\u0627\u0644\u0648\u0627: \u064a\u0627 \u0645\u062d\u0645\u062f \u0641\u0635\u0641 \u0644\u0646\u0627 \u0628\u064a\u062a \u0627\u0644\u0645\u0642\u062f\u0633\u060c \u0642\u0627\u0644: \u062f\u062e\u0644\u062a \u0644\u064a\u0644\u0627\u064b\u060c \u0648\u062e\u0631\u062c\u062a \u0644\u064a\u0644\u0627\u064b \u0641\u0623\u062a\u0627\u0647 \u062c\u0628\u0631\u064a\u0644 \u0628\u0635\u0648\u0631\u062a\u0647 \u0641\u064a \u062c\u0646\u0627\u062d\u0647\u060c \u0641\u062c\u0639\u0644 \u064a\u0642\u0648\u0644: \u0628\u0627\u0628 \u0645\u0646\u0647 \u0643\u0630\u0627\u060c \u0641\u064a \u0645\u0648\u0636\u0639 \u0643\u0630\u0627\u060c \u0648\u0628\u0627\u0628 \u0645\u0646\u0647 \u0643\u0630\u0627\u060c \u0641\u064a \u0645\u0648\u0636\u0639 \u0643\u0630\u0627.",null)
