B.aFz=new A.a("\u0648\u0644\u0645\u0627 \u0631\u0623\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u062d\u0645\u0632\u0629 \u0628\u0646 \u0639\u0628\u062f\u0627\u0644\u0645\u0637\u0644\u0628 \u0648\u0642\u062f \u0645\u062b\u0644 \u0628\u0647 \u062d\u0632\u0646 \u062d\u0632\u0646\u0627\u064b \u0634\u062f\u064a\u062f\u0627\u064b\u060c \u0648\u0628\u0643\u0649 \u062d\u062a\u0649 \u0646\u0634\u063a \u0645\u0646 \u0627\u0644\u0628\u0643\u0627\u0621 \u0648\u0642\u0627\u0644 \ufdfa : \u0644\u0648\u0644\u0627 \u0623\u0646 \u062a\u062d\u0632\u0646 \u0635\u0641\u064a\u0629 \u0648\u064a\u0643\u0648\u0646 \u0633\u0646\u0629 \u0645\u0646 \u0628\u0639\u062f\u064a \u0644\u062a\u0631\u0643\u062a\u0647 \u062d\u062a\u0649 \u064a\u0643\u0648\u0646 \u0641\u064a \u0628\u0637\u0648\u0646 \u0627\u0644\u0633\u0628\u0627\u0639 \u0648\u062d\u0648\u0627\u0635\u0644 \u0627\u0644\u0637\u064a\u0631\u060c \u0648\u0644\u0626\u0646 \u0623\u0638\u0647\u0631\u0646\u064a \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0642\u0631\u064a\u0634 \u0641\u064a \u0645\u0648\u0637\u0646 \u0645\u0646 \u0627\u0644\u0645\u0648\u0627\u0637\u0646 \u0644\u0623\u0645\u062b\u0644\u0646 \u0628\u062b\u0644\u0627\u062b\u064a\u0646 \u0631\u062c\u0644\u0627\u064b \u0645\u0646\u0647\u0645 \u0641\u0644\u0645\u0627 \u0631\u0623\u0649 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u062d\u0632\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u063a\u064a\u0638\u0647 \u0639\u0644\u0649 \u0645\u0646 \u0641\u0639\u0644 \u0628\u0639\u0645\u0647 \u0645\u0627\u0641\u0639\u0644 \u0642\u0627\u0644\u0648\u0627: \u0648\u0627\u0644\u0644\u0647 \u0644\u0626\u0646 \u0638\u0641\u0631\u0646\u0627 \u0627\u0644\u0644\u0647 \u0628\u0647\u0645 \u064a\u0648\u0645\u0627\u064b \u0645\u0646 \u0627\u0644\u062f\u0647\u0631 \u0644\u0646\u0645\u062b\u0644\u0646 \u0628\u0647\u0645 \u0645\u064f\u062b\u0644\u064e\u0629 \u0644\u0645 \u064a\u0645\u062b\u0644\u0647\u0627 \u0623\u062d\u062f \u0645\u0646 \u0627\u0644\u0639\u0631\u0628 \u0641\u0646\u0632\u0644 \u0642\u0648\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: \u0648\u064e\u0625\u0650\u0646\u0652 \u0639\u064e\u0627\u0642\u064e\u0628\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0639\u064e\u0627\u0642\u0650\u0628\u064f\u0648\u0627 \u0628\u0650\u0645\u0650\u062b\u0652\u0644\u0650 \u0645\u064e\u0627 \u0639\u064f\u0648\u0642\u0650\u0628\u0652\u062a\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0635\u064e\u0628\u064e\u0631\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0647\u064f\u0648\u064e \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u0650\u0644\u0635\u0651\u064e\u0627\u0628\u0650\u0631\u0650\u064a\u0646\u064e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0646\u062d\u0644 \u060c\u0644\u0642\u062f \u0627\u0631\u062a\u0643\u0628 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0635\u0648\u0631\u0627\u064b \u0645\u0646 \u0627\u0644\u0648\u062d\u0634\u064a\u0629 \u062d\u064a\u062b \u0642\u0627\u0645\u0648\u0627 \u0628\u0627\u0644\u062a\u0645\u062b\u064a\u0644 \u0641\u064a \u0642\u062a\u0644\u0649 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0641\u0628\u0642\u0631\u0648\u0627 \u0628\u0637\u0648\u0646 \u0643\u062b\u064a\u0631 \u0645\u0646 \u0627\u0644\u0642\u062a\u0644\u0649 \u0648\u062c\u062f\u0639\u0648\u0627 \u0623\u0646\u0648\u0641\u0647\u0645 \u0648\u0642\u0637\u0639\u0648\u0627 \u0627\u0644\u0622\u0630\u0627\u0646 \u0648\u0645\u0630\u0627\u0643\u064a\u0631 \u0628\u0639\u0636\u0647\u0645.",null)
B.aJo=new A.a("\u0648\u0645\u0639 \u0630\u0644\u0643 \u0635\u0628\u0631 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0623\u0635\u062d\u0627\u0628\u0647 \u0648\u0627\u0633\u062a\u062c\u0627\u0628\u0648\u0627 \u0644\u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u0645\u0648\u0644\u0649 \u0639\u0632\u0648\u062c\u0644 \u0641\u0639\u0641\u0627 \u0648\u0635\u0628\u0631 \u0648\u0643\u0641\u0651\u0631 \u0639\u0646 \u064a\u0645\u064a\u0646\u0647 \u0648\u0646\u0647\u0649 \u0639\u0646 \u0627\u0644\u0645\u062b\u0644\u0629 \u0631\u0648\u0649 \u0627\u0628\u0646 \u0627\u0633\u062d\u0627\u0642 \u0628\u0633\u0646\u062f\u0647 \u0639\u0646 \u0633\u0645\u0631\u0629 \u0628\u0646 \u062c\u0646\u062f\u0628 \u0642\u0627\u0644:\u0645\u0627\u0642\u0627\u0645 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u064a \u0645\u0642\u0627\u0645 \u0642\u0637 \u0641\u0641\u0627\u0631\u0642\u0647 \u062d\u062a\u0649 \u064a\u0623\u0645\u0631\u0646\u0627 \u0628\u0627\u0644\u0635\u062f\u0642\u0629 \u0648\u064a\u0646\u0647\u0627\u0646\u0627 \u0639\u0646 \u0627\u0644\u0645\u062b\u0644\u0629.",null)
