B.b18=new A.a("\u0648\u0639\u0627\u062f \u0625\u0644\u0649 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0645\u0638\u0641\u0631\u0627\u064b \u064a\u0639\u062f \u0623\u0628\u0648 \u0633\u0644\u0645\u0629 \u0645\u0646 \u0627\u0644\u0633\u0627\u0628\u0642\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0645\u0646 \u062e\u064a\u0631\u0629 \u0627\u0644\u0631\u0639\u064a\u0644 \u0627\u0644\u0623\u0648\u0644\u060c \u0648\u0642\u062f \u0639\u0627\u062f \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u063a\u0632\u0648\u0629 \u0645\u062a\u0639\u0628\u0627\u064b \u0625\u0630 \u0646\u063a\u0631 \u062c\u0631\u062d\u0647 \u0627\u0644\u0630\u064a \u0623\u0635\u0627\u0628\u0647 \u0641\u064a \u0623\u062d\u062f \u0641\u0644\u0645 \u064a\u0644\u0628\u062b \u062d\u062a\u0649 \u0645\u0627\u062a \u0648\u0646\u0644\u062d\u0638 \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0633\u0631\u064a\u0629 \u0639\u062f\u0629 \u0623\u0645\u0648\u0631 \u0645\u0646\u0647\u0627: \u0627\u0644\u062f\u0642\u0629 \u0641\u064a \u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u062d\u0631\u0628\u064a \u0639\u0646\u062f \u0627\u0644\u0646\u0628\u064a \ufdfa \u062d\u064a\u062b \u0641\u0631\u0642 \u0623\u0639\u062f\u0627\u0621\u0647 \u0642\u0628\u0644 \u0623\u0646 \u064a\u062c\u062a\u0645\u0639\u0648\u0627\u060c \u0641\u0630\u0647\u0644\u0648\u0627 \u0644\u0645\u062c\u0626 \u0633\u0631\u064a\u0629 \u0623\u0628\u064a \u0633\u0644\u0645\u0629 \u0648\u0647\u0645 \u064a\u0638\u0646\u0648\u0646 \u0623\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0642\u062f \u0623\u0636\u0639\u0641\u062a\u0647\u0645 \u0648\u0642\u0639\u0629 \u0623\u062d\u062f \u0648\u0623\u0630\u0647\u0644\u062a\u0647\u0645 \u0639\u0646 \u0623\u0646\u0641\u0633\u0647\u0645\u060c \u0641\u0623\u0635\u064a\u0628 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0628\u0627\u0644\u0631\u0639\u0628 \u0645\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0648\u0648\u0647\u062a \u0639\u0632\u064a\u0645\u062a\u0647\u0645 \u0648\u0627\u0646\u0634\u063a\u0644\u0648\u0627 \u0628\u0623\u0646\u0641\u0633\u0647\u0645 \u0639\u0646 \u0645\u0647\u0627\u062c\u0645\u0629 \u0627\u0644\u0645\u062f\u064a\u0646\u0629\u060c \u0648\u062a\u0638\u0647\u0631 \u062f\u0642\u0629 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0641\u064a \u0627\u0644\u0631\u0635\u062f \u0627\u0644\u062d\u0631\u0628\u064a \u0648\u0627\u062e\u062a\u064a\u0627\u0631\u0647\u0645 \u0627\u0644\u062a\u0648\u0642\u064a\u062a \u0627\u0644\u0635\u062d\u064a\u062d \u0648\u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0645\u0646\u0627\u0633\u0628 \u062d\u064a\u062b \u0648\u0635\u0644\u0648\u0627 \u0625\u0644\u0649 \u0627\u0644\u0623\u0639\u062f\u0627\u0621 \u0642\u0628\u0644 \u0623\u0646 \u064a\u0639\u0644\u0645\u0648\u0627 \u0639\u0646\u0647\u0645 \u0623\u064a \u0634\u064a\u0621 \u0631\u063a\u0645 \u0628\u0639\u062f \u0627\u0644\u0645\u0633\u0627\u0641\u0629\u060c \u0648\u0643\u0627\u0646 \u0647\u0630\u0627 \u0647\u0648 \u0623\u0647\u0645 \u0639\u0648\u0627\u0645\u0644 \u0646\u062c\u0627\u062d \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0633\u0631\u064a\u0629 \u0648\u062a\u0631\u0643\u062a \u0647\u0630\u0647 \u0627\u0644\u0633\u0631\u064a\u0629 \u0641\u064a \u0646\u0641\u0648\u0633 \u0627\u0644\u0623\u0639\u062f\u0627\u0621 \u0634\u0639\u0648\u0631\u0627\u064b \u0645\u0624\u062b\u0631\u0627\u064b \u0639\u0644\u0649 \u0645\u0639\u0646\u0648\u064a\u0627\u062a\u0647\u0645 \u0623\u0644\u0627 \u0648\u0647\u0648 \u0642\u0646\u0627\u0639\u062a\u0647\u0645 \u0628\u0642\u062f\u0631\u0629 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0627\u0633\u062a\u062e\u0641\u0627\u0621 \u0648\u0627\u0644\u0642\u064a\u0627\u0645 \u0628\u0627\u0644\u062d\u0631\u0648\u0628 \u0627\u0644\u062e\u0627\u0637\u0641\u0629 \u0627\u0644\u0645\u0641\u0627\u062c\u0626\u0629 \u062a\u062c\u0639\u0644\u0647\u0645 \u064a\u0645\u062a\u0644\u0626\u0648\u0646 \u0631\u0639\u0628\u0627\u064b \u0645\u0646\u0647\u0645 \u0648\u064a\u062a\u0648\u0642\u0639\u0648\u0646 \u0627\u0644\u0625\u063a\u0627\u0631\u0629 \u0641\u064a \u0623\u064a \u0648\u0642\u062a\u060c \u0648\u0647\u0630\u0627 \u0627\u0644\u0634\u0639\u0648\u0631 \u062d\u0645\u0644\u0647\u0645 \u0639\u0644\u0649 \u0627\u0644\u0627\u0639\u062a\u0631\u0627\u0641 \u0628\u0642\u0648\u0629 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0648\u0645\u0633\u0627\u0644\u0645\u062a\u0647\u0645.",null)
