B.avW=new A.a("\u0642\u0627\u0644\u062a \u0623\u0645 \u0633\u0644\u0645\u0629: \u0641\u0644\u0645\u0627 \u062e\u0631\u062c\u0627 \u0639\u0645\u0631\u0648 \u0628\u0646 \u0627\u0644\u0639\u0627\u0635\u060c \u0648\u0639\u0628\u062f \u0627\u0644\u0644\u0647 \u0628\u0646 \u0623\u0628\u064a \u0631\u0628\u064a\u0639\u0629 \u0645\u0646 \u0639\u0646\u062f\u0647 \u0642\u0627\u0644 \u0639\u0645\u0631\u0648 \u0628\u0646 \u0627\u0644\u0639\u0627\u0635: \u0648\u0627\u0644\u0644\u0647 \u0644\u0623\u0646\u0628\u0626\u0646\u0647 \u063a\u062f\u064b\u0627 \u0639\u064a\u0628\u0647\u0645 \u0639\u0646\u062f\u0647\u060c \u062b\u0645 \u0623\u0633\u062a\u0623\u0635\u0644 \u0628\u0647 \u062e\u0636\u0631\u0627\u0621\u0647\u0645 - \u0623\u064a \u0623\u0642\u0636\u064a \u0628\u0647 \u0639\u0644\u0649 \u062f\u0647\u0645\u0627\u0626\u0647\u0645 \u0648\u0633\u0648\u0627\u062f\u0647\u0645- \u0642\u0627\u0644\u062a: \u0641\u0642\u0627\u0644 \u0644\u0647 \u0639\u0628\u062f \u0627\u0644\u0644\u0647 \u0628\u0646 \u0623\u0628\u064a \u0631\u0628\u064a\u0639\u0629\u060c \u0648\u0643\u0627\u0646 \u0623\u062a\u0642\u0649 \u0627\u0644\u0631\u062c\u0644\u064a\u0646 \u0641\u064a\u0646\u0627\u060c \u0644\u0627 \u062a\u0641\u0639\u0644\u060c \u0641\u0625\u0646 \u0644\u0647\u0645 \u0623\u0631\u062d\u0627\u0645\u064b\u0627 \u0648\u0625\u0646 \u0643\u0627\u0646\u0648\u0627 \u0642\u062f \u062e\u0627\u0644\u0641\u0648\u0646\u0627.",null)
B.awB=new A.a("\u0642\u0627\u0644: \u0648\u0627\u0644\u0644\u0647 \u0644\u0623\u062e\u0628\u0631\u0646\u0647 \u0623\u0646\u0647\u0645 \u064a\u0632\u0639\u0645\u0648\u0646 \u0623\u0646 \u0639\u064a\u0633\u0649 \u0627\u0628\u0646 \u0645\u0631\u064a\u0645 \u0639\u0628\u062f\u060c \u0642\u0627\u0644\u062a: \u062b\u0645 \u063a\u062f\u0627 \u0639\u0644\u064a\u0647 \u0627\u0644\u063a\u062f \u0641\u0642\u0627\u0644 \u0644\u0647: \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0644\u0643 \u0625\u0646\u0647\u0645 \u064a\u0642\u0648\u0644\u0648\u0646 \u0641\u064a \u0639\u064a\u0633\u0649 \u0627\u0628\u0646 \u0645\u0631\u064a\u0645 \u0642\u0648\u0644\u0627\u064b \u0639\u0638\u064a\u0645\u064b\u0627 \u0641\u0623\u0631\u0633\u0644 \u0625\u0644\u064a\u0647\u0645 \u0641\u0627\u0633\u0623\u0644\u0647\u0645 \u0639\u0645\u0627 \u064a\u0642\u0648\u0644\u0648\u0646 \u0641\u064a\u0647\u060c \u0642\u0627\u0644\u062a: \u0641\u0623\u0631\u0633\u0644 \u0625\u0644\u064a\u0647\u0645 \u064a\u0633\u0623\u0644\u0647\u0645 \u0639\u0646\u0647\u060c \u0642\u0627\u0644\u062a: \u0648\u0644\u0645 \u064a\u0646\u0632\u0644 \u0628\u0646\u0627 \u0645\u062b\u0644\u0647\u0627\u060c \u0641\u0627\u062c\u062a\u0645\u0639 \u0627\u0644\u0642\u0648\u0645 \u0641\u0642\u0627\u0644 \u0628\u0639\u0636\u0647\u0645 \u0644\u0628\u0639\u0636: \u0645\u0627\u0630\u0627 \u062a\u0642\u0648\u0644\u0648\u0646 \u0641\u064a \u0639\u064a\u0633\u0649 \u0625\u0630\u0627 \u0633\u0623\u0644\u0643\u0645 \u0639\u0646\u0647\u061f \u0642\u0627\u0644\u0648\u0627: \u0646\u0642\u0648\u0644 \u0648\u0627\u0644\u0644\u0647 \u0641\u064a\u0647\u060c \u0645\u0627 \u0642\u0627\u0644 \u0627\u0644\u0644\u0647\u060c \u0648\u0645\u0627 \u062c\u0627\u0621 \u0628\u0647 \u0646\u0628\u064a\u0646\u0627 \u0643\u0627\u0626\u0646\u064b\u0627 \u0641\u064a \u0630\u0644\u0643 \u0645\u0627 \u0647\u0648 \u0643\u0627\u0626\u0646\u060c \u0641\u0644\u0645\u0627 \u062f\u062e\u0644\u0648\u0627 \u0639\u0644\u064a\u0647\u060c \u0642\u0627\u0644 \u0644\u0647\u0645: \u0645\u0627 \u062a\u0642\u0648\u0644\u0648\u0646 \u0641\u064a \u0639\u064a\u0633\u0649 \u0627\u0628\u0646 \u0645\u0631\u064a\u0645\u061f \u0641\u0642\u0627\u0644 \u0644\u0647 \u062c\u0639\u0641\u0631 \u0628\u0646 \u0623\u0628\u064a \u0637\u0627\u0644\u0628: \u0646\u0642\u0648\u0644 \u0641\u064a\u0647 \u0627\u0644\u0630\u064a \u062c\u0627\u0621 \u0628\u0647 \u0646\u0628\u064a\u0646\u0627: \u0647\u0648 \u0639\u0628\u062f \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0631\u0648\u062d\u0647\u060c \u0648\u0643\u0644\u0645\u062a\u0647 \u0623\u0644\u0642\u0627\u0647\u0627 \u0625\u0644\u0649 \u0645\u0631\u064a\u0645 \u0627\u0644\u0639\u0630\u0631\u0627\u0621 \u0627\u0644\u0628\u062a\u0648\u0644.",null)
B.aIr=new A.a("\u0642\u0627\u0644\u062a: \u0641\u0636\u0631\u0628 \u0627\u0644\u0646\u062c\u0627\u0634\u064a \u064a\u062f\u0647 \u0625\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0641\u0623\u062e\u0630 \u0645\u0646\u0647\u0627 \u0639\u0648\u062f\u064b\u0627\u060c \u062b\u0645 \u0642\u0627\u0644: \u0645\u0627 \u0639\u062f\u0627 \u0639\u064a\u0633\u0649 \u0627\u0628\u0646 \u0645\u0631\u064a\u0645 \u0645\u0627 \u0642\u0644\u062a \u0647\u0630\u0627 \u0627\u0644\u0639\u0648\u062f \u0641\u062a\u0646\u0627\u062e\u0631\u062a - \u0623\u064a \u062a\u0643\u0644\u0645\u062a \u0648\u0643\u0623\u0646\u0647 \u0643\u0644\u0627\u0645 \u0645\u0639 \u063a\u0636\u0628 \u0648\u0646\u0641\u0648\u0631- \u0628\u0637\u0627\u0631\u0642\u062a\u0647 \u062d\u0648\u0644\u0647 \u062d\u064a\u0646 \u0642\u0627\u0644 \u0645\u0627 \u0642\u0627\u0644\u060c \u0641\u0642\u0627\u0644: \u0648\u0625\u0646 \u0646\u062e\u0631\u062a\u0645 \u0648\u0627\u0644\u0644\u0647\u060c \u0627\u0630\u0647\u0628\u0648\u0627 \u0641\u0623\u0646\u062a\u0645 \u0633\u064a\u0648\u0645 \u0628\u0623\u0631\u0636\u064a \u0648\u0627\u0644\u0633\u064a\u0648\u0645 \u0627\u0644\u0622\u0645\u0646\u0648\u0646 \u0645\u0646 \u0633\u0628\u0643\u0645 \u063a\u0631\u0645\u060c \u062b\u0645 \u0645\u0646 \u0633\u0628\u0643\u0645 \u063a\u0631\u0645\u060c \u0641\u0645\u0627 \u0623\u062d\u0628 \u0623\u0646 \u0644\u064a \u062f\u064e\u0628\u0631\u064b\u0627 \u0630\u0647\u0628\u064b\u0627\u060c \u0648\u0625\u0646\u064a \u0622\u0630\u064a\u062a \u0631\u062c\u0644\u0627 \u0645\u0646\u0643\u0645\u060c \u0648\u0627\u0644\u062f\u0628\u0631 \u0628\u0644\u0633\u0627\u0646 \u0627\u0644\u062d\u0628\u0634\u0629 \u0627\u0644\u062c\u0628\u0644\u060c \u0631\u062f\u0648\u0627 \u0639\u0644\u064a\u0647\u0645\u0627 \u0647\u062f\u0627\u064a\u0627\u0647\u0645\u0627 \u0641\u0644\u0627 \u062d\u0627\u062c\u0629 \u0644\u0646\u0627 \u0628\u0647\u0627\u060c \u0641\u0648\u0627\u0644\u0644\u0647 \u0645\u0627 \u0623\u062e\u0630 \u0627\u0644\u0644\u0647 \u0645\u0646\u064a \u0627\u0644\u0631\u0634\u0648\u0629 \u062d\u064a\u0646 \u0631\u062f \u0639\u0644\u064a\u0651\u064e \u0645\u0644\u0643\u064a\u060c \u0641\u0622\u062e\u0630 \u0627\u0644\u0631\u0634\u0648\u0629 \u0641\u064a\u0647\u060c \u0648\u0645\u0627 \u0623\u0637\u0627\u0639 \u0627\u0644\u0646\u0627\u0633\u064e \u0641\u064a \u0641\u0623\u0637\u064a\u0639\u0647\u0645 \u0641\u064a\u0647\u060c \u0642\u0627\u0644\u062a: \u0641\u062e\u0631\u062c\u0627 \u0645\u0646 \u0639\u0646\u062f\u0647 \u0645\u0642\u0628\u0648\u062d\u064a\u0646 \u0645\u0631\u062f\u0648\u062f\u064b\u0627 \u0639\u0644\u064a\u0647\u0645\u0627\u060c \u0645\u0627 \u062c\u0627\u0621\u0627 \u0628\u0647 \u0648\u0623\u0642\u0645\u0646\u0627 \u0639\u0646\u062f\u0647 \u0628\u062e\u064a\u0631 \u062f\u0627\u0631 \u0645\u0639 \u062e\u064a\u0631 \u062c\u0627\u0631.",null)
